		/** 
		 * Tests creating a new Customer.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Customer");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Customer" );

			try {            
				Customer entity = CustomerService.getCustomerInstance().createCustomer( generateNewEntity() );
				thePrimaryKey = entity.getCustomerId();
				LOGGER.info( "-- Successfully created a Customer with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Customer. 
		 */
		public Customer testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Customer" );

			Customer entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Customer with primary key" );
			msg.append( thePrimaryKey );
			
			CustomerFetchOneSummary fetchOneSummary = new CustomerFetchOneSummary( thePrimaryKey );

			try {
				entity = CustomerService.getCustomerInstance().getCustomer( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Customer " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Customer.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Customer." );

			StringBuilder msg = new StringBuilder( "Failed to update a Customer : " );        
			Customer entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Customer." );

				// for use later on...
				thePrimaryKey = entity.getCustomerId();

				CustomerService proxy = CustomerService.getCustomerInstance();            
				proxy.updateCustomer( entity );   

				LOGGER.info( "-- Successfully saved Customer - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Customer.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Customer." );

			try{
			    Customer entity = testRead(); 
				CustomerService.getCustomerInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Customer with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Customer with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Customers.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Customers:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Customer : " );        
			List<Customer> collection  = null;

			try {
				// call the static get method on the CustomerService
				collection = CustomerService.getCustomerInstance().getAllCustomer();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Customer entity = null;            
					Iterator<Customer> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getCustomerId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

